<div id="ui"><div class="jp">神奈川沖浪裏</div></div>
<div id="credit">after Katsushika Hokusai, The Great Wave off Kanagawa (ca. 1831)</div>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

// Palette sampled from the print
const C = {
  cream: 0xefe3c2, grayCloud: 0x8f887e,
  deep: 0x1b4477, prussian: 0x2b5d8c, mid: 0x4a7fab,
  foam: 0xdce6dd, paper: 0xf2ecd9, ochre: 0xd9b98a, dark: 0x14304f
};

const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(C.cream);
scene.fog = new THREE.Fog(C.cream, 90, 190);

const camera = new THREE.PerspectiveCamera(42, innerWidth/innerHeight, 0.1, 400);
camera.position.set(6, 14, 46);
camera.lookAt(-2, 7, -10);

scene.add(new THREE.HemisphereLight(0xfff6e0, 0x2b5d8c, 1.2));
const sun = new THREE.DirectionalLight(0xfff2d0, 1.5);
sun.position.set(-14, 26, 20);
scene.add(sun);

function mat(color, double=false){
  return new THREE.MeshPhongMaterial({color, flatShading:true, shininess:12, side: double?THREE.DoubleSide:THREE.FrontSide});
}

// ---------- Mount Fuji: small snow-capped cone, horizon center-right ----------
function makeFuji(){
  const g = new THREE.Group();
  const cone = new THREE.Mesh(new THREE.CylinderGeometry(0.6, 7, 5.5, 7, 1), mat(C.prussian));
  cone.position.y = 2.75; g.add(cone);
  const snow = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 2.6, 1.8, 7, 1), mat(C.paper));
  snow.position.y = 4.6; g.add(snow);
  const cap = new THREE.Mesh(new THREE.ConeGeometry(0.6, 0.8, 7), mat(C.paper));
  cap.position.y = 5.75; g.add(cap);
  g.position.set(16, 5.5, -90);
  return g;
}
scene.add(makeFuji());

// gray cloud band across the horizon (as in the print)
const cloud = new THREE.Mesh(new THREE.PlaneGeometry(220, 10),
  new THREE.MeshBasicMaterial({color:C.grayCloud, transparent:true, opacity:0.5}));
cloud.position.set(6, 12, -110);
scene.add(cloud);

// ---------- rolling sea ----------
const seaGeo = new THREE.PlaneGeometry(220, 130, 30, 20);
seaGeo.rotateX(-Math.PI/2);
const sea = new THREE.Mesh(seaGeo, mat(C.deep));
scene.add(sea);
const basePos = seaGeo.attributes.position.array.slice();

// ---------- The Great Wave: left, curling right, foam claws ----------
function claw(len){
  const g = new THREE.Group();
  for(let i=0;i<7;i++){
    const t = i/6;
    const seg = new THREE.Mesh(
      new THREE.BoxGeometry(len*0.34*(1-t*0.7), 0.75*(1-t*0.5), 0.9),
      mat(i%2 ? C.paper : C.foam));
    seg.position.set(t*len*0.42, Math.sin(t*2.0)*1.0 + 0.4, (i%3-1)*0.35);
    seg.rotation.z = -t*1.0;
    g.add(seg);
  }
  return g;
}

